function buildBsoResultPackage(row, sha256) {
  function record(value) {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    try { const parsed = JSON.parse(value); if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed; } catch (_) {}
    return {};
  }
  const receipt = record(row?.bso_receipt || row?.bso_receipt_json), audit = record(row?.audit_json);
  const scope = record(row?.operation_receipt || audit.operation_receipt || row?.provider_receipt);
  const guard = record(row?.verification_receipt || audit.verification_receipt);
  const hash = value => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
  if (!row || receipt.schema_version !== 'lk-bso-receipt/1.0' || !/^BSO_[A-Za-z0-9_-]{1,76}$/.test(receipt.job_id || '') || !/^WORK_DOC_\d+$/.test(receipt.document_id || '') || !Number.isSafeInteger(receipt.revision) || receipt.revision < 1 || !hash(receipt.artifact_sha256) || !hash(receipt.input_sha256) || !hash(receipt.output_sha256) || typeof receipt.execution_id !== 'string' || !receipt.execution_id || receipt.execution_id.length > 128 || receipt.human_approved !== false) throw Error('BSO_RESULT_RECEIPT_INVALID');
  if (row.job_id !== receipt.job_id || row.input_sha256 !== receipt.input_sha256 || String(row.worker_execution_id || '') !== receipt.execution_id || row.status !== receipt.status || !['NEEDS_GPT_REVIEW', 'BLOCKED'].includes(row.status)) throw Error('BSO_RESULT_QUEUE_BINDING');
  if (typeof row.output !== 'string' || row.output.length > 100000 || sha256(row.output) !== receipt.output_sha256 || row.output_sha256 !== receipt.output_sha256) throw Error('BSO_RESULT_OUTPUT_BINDING');
  if (row.status === 'BLOCKED' && row.output !== '') throw Error('BSO_BLOCKED_OUTPUT_NOT_EMPTY');
  if (row.status === 'NEEDS_GPT_REVIEW' && (!row.output.trim() || guard.format_and_guard_passed !== true || scope.input_body_sha256 !== receipt.input_sha256 || !Array.isArray(scope.approval_scope_violations) || scope.approval_scope_violations.length !== 0)) throw Error('BSO_RESULT_GUARD_REQUIRED');
  return {
    schema_version: 'lk-bso-result/1.0',
    bso_receipt: Object.fromEntries(['schema_version', 'job_id', 'document_id', 'revision', 'artifact_sha256', 'input_sha256', 'output_sha256', 'execution_id', 'status', 'human_approved'].map(key => [key, receipt[key]])),
    output: row.output,
    verification: { output_sha256_checked: true, provider_guard_passed: row.status === 'NEEDS_GPT_REVIEW', human_approved: false, legal_accuracy_approved: false },
    evidence_source: 'EXPORTED_QUEUE_METADATA_NOT_AUTHENTICATED',
  };
}
function reviewPassed(review) {
  if (!review || typeof review.pass !== 'boolean' || !Array.isArray(review.issues) || !Array.isArray(review.constraints) || !Array.isArray(review.unresolved)) throw Error('INVALID_REVIEW_SCHEMA');
  if (review.issues.some((item) => !item || !['critical', 'major', 'minor'].includes(item.severity)) || review.constraints.some((item) => !item || typeof item.pass !== 'boolean')) throw Error('INVALID_REVIEW_SCHEMA');
  return review.pass === true && review.unresolved.length === 0 && !review.issues.some((item) => ['critical', 'major'].includes(item.severity)) && review.constraints.every((item) => item.pass === true);
}

function validateQueueInput(job, sha256) {
  if (!job || !['SYNTHETIC', 'PUBLIC'].includes(job.data_class)) throw Error('QUEUE_PRIVATE_DATA_BLOCKED');
  if (typeof job.prompt !== 'string' || !job.prompt.trim() || job.prompt.length > 24000) throw Error('QUEUE_PROMPT_INVALID');
  if (job.status !== 'RUNNING' || typeof job.job_id !== 'string' || !/^[A-Za-z0-9_-]{1,128}$/.test(job.job_id)) throw Error('QUEUE_CLAIM_REQUIRED');
  if (!/^[a-f0-9]{64}$/.test(job.input_sha256 || '') || sha256(job.prompt) !== job.input_sha256) throw Error('QUEUE_INPUT_BINDING_FAILED');
  if (!['1', '2'].includes(String(job.attempts))) throw Error('QUEUE_ATTEMPT_LIMIT');
  if (job.bso_context !== undefined) {
    const c = job.bso_context;
    if (!c || c.schema_version !== 'lk-bso-job/1.0' || typeof c.document_id !== 'string' || !/^WORK_DOC_\d+$/.test(c.document_id) || !Number.isSafeInteger(c.revision) || c.revision < 1 || !/^[a-f0-9]{64}$/.test(c.artifact_sha256 || '')) throw Error('BSO_CONTEXT_INVALID');
  }
  return { ...job, chatInput: `/${job.data_class === 'PUBLIC' ? 'public' : 'synthetic'} ${job.prompt}` };
}

function buildQueueResult(result, job, executionId, sha256) {
  function parseRecord(value) {
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    if (typeof value !== 'string') return {};
    try { const parsed = JSON.parse(value); return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}; } catch (_) { return {}; }
  }
  const audit = parseRecord(result?.audit_json);
  const output = typeof result?.output === 'string' ? result.output : '';
  const outputHash = sha256(output);
  const receipt = result?.verification_receipt || audit.verification_receipt;
  const scope = result?.operation_receipt || audit.operation_receipt || parseRecord(result?.provider_receipt);
  const valid = !result?.error && result?.job_id === job.job_id && result?.output_sha256 === outputHash && result?.review_status === 'PENDING' && result?.status === 'NEEDS_GPT_REVIEW' && receipt?.format_and_guard_passed === true && scope?.input_body_sha256 === job.input_sha256 && (audit.input_sha256 === undefined || audit.input_sha256 === job.input_sha256) && Array.isArray(scope?.approval_scope_violations) && scope.approval_scope_violations.length === 0 && output.trim().length > 0;
  return {
    ...result, job_id: job.job_id, worker_execution_id: String(executionId), input_sha256: job.input_sha256,
    status: valid ? 'NEEDS_GPT_REVIEW' : 'BLOCKED', review_status: 'PENDING',
    output: valid ? output : '', output_sha256: valid ? outputHash : sha256(''),
    error_code: valid ? '' : 'WORKER_RESULT_BINDING_OR_REVIEW_FAILED', operation_receipt: scope || {}, verification_receipt: receipt || {},
    ...(job.bso_context ? { bso_receipt: {
      ...job.bso_context,
      // Context's schema describes a request; the result always uses the receipt schema.
      schema_version: 'lk-bso-receipt/1.0', job_id: job.job_id,
      input_sha256: job.input_sha256, output_sha256: valid ? outputHash : sha256(''),
      execution_id: String(executionId), status: valid ? 'NEEDS_GPT_REVIEW' : 'BLOCKED',
      human_approved: false, recorded_at: new Date().toISOString(),
    } } : {}),
  };
}

const sha=v=>require('crypto').createHash('sha256').update(v,'utf8').digest('hex');

const tests=[];function check(name,fn){let passed=false;try{passed=fn()===true;}catch(_){}tests.push({name,passed});}function rejected(fn){try{fn();return false;}catch(_){return true;}}
const review={pass:true,issues:[],constraints:[{pass:true}],unresolved:[]};
check('clean review passes',()=>reviewPassed(review));
check('unresolved blocks',()=>!reviewPassed({...review,unresolved:['needs original']}));
check('major issue blocks',()=>!reviewPassed({...review,issues:[{severity:'major'}]}));
check('null issue rejected',()=>rejected(()=>reviewPassed({...review,issues:[null]})));
const job={job_id:'SYNTHETIC_QA_001',status:'RUNNING',attempts:1,data_class:'SYNTHETIC',prompt:'Synthetic workflow contract check',input_sha256:sha('Synthetic workflow contract check'),bso_context:{schema_version:'lk-bso-job/1.0',document_id:'WORK_DOC_1',revision:1,artifact_sha256:sha('synthetic bytes')}};
check('valid synthetic request',()=>validateQueueInput(job,sha).chatInput.startsWith('/synthetic '));
check('public classification preserved',()=>validateQueueInput({...job,data_class:'PUBLIC'},sha).chatInput.startsWith('/public '));
for(const attempts of [undefined,'',0,-1,3,1.5,'01',' 1 '])check('invalid attempt '+String(attempts),()=>rejected(()=>validateQueueInput({...job,attempts},sha)));
check('private data blocked',()=>rejected(()=>validateQueueInput({...job,data_class:'CONFIDENTIAL'},sha)));
check('changed input blocked',()=>rejected(()=>validateQueueInput({...job,prompt:'changed'},sha)));
const result={job_id:job.job_id,status:'NEEDS_GPT_REVIEW',review_status:'PENDING',output:'Synthetic draft',output_sha256:sha('Synthetic draft'),audit_json:JSON.stringify({input_sha256:job.input_sha256,verification_receipt:{format_and_guard_passed:true},operation_receipt:{input_body_sha256:job.input_sha256,approval_scope_violations:[]}})};
check('native envelope supported',()=>buildQueueResult(result,job,$execution.id,sha).status==='NEEDS_GPT_REVIEW');
check('changed output blocked',()=>buildQueueResult({...result,output:'changed'},job,$execution.id,sha).status==='BLOCKED');
check('other job blocked',()=>buildQueueResult({...result,job_id:'OTHER'},job,$execution.id,sha).status==='BLOCKED');
check('automatic DONE blocked',()=>buildQueueResult({...result,status:'DONE'},job,$execution.id,sha).status==='BLOCKED');
check('human approval remains false',()=>buildQueueResult(result,job,$execution.id,sha).bso_receipt.human_approved===false);

const bsoJob={...job,job_id:'BSO_SYNTHETIC_RETURN_QA'};
const bsoFixture={...result,job_id:bsoJob.job_id,secret:'NEVER_EXPORT'};
const bsoResult=buildQueueResult(bsoFixture,bsoJob,$execution.id,sha);
check('BSO result package body matches',()=>buildBsoResultPackage(bsoResult,sha).output==='Synthetic draft');
check('BSO result content tamper rejected',()=>rejected(()=>buildBsoResultPackage({...bsoResult,output:'tampered'},sha)));
check('BSO result worker mismatch rejected',()=>rejected(()=>buildBsoResultPackage({...bsoResult,worker_execution_id:'OTHER'},sha)));
check('BSO result guard required',()=>rejected(()=>buildBsoResultPackage({...bsoResult,verification_receipt:{format_and_guard_passed:false}},sha)));
check('BSO result cannot approve human',()=>buildBsoResultPackage(bsoResult,sha).verification.human_approved===false);
check('BSO result prompt omitted',()=>!JSON.stringify(buildBsoResultPackage(bsoResult,sha)).includes(bsoJob.prompt));
check('BSO arbitrary fields omitted',()=>!JSON.stringify(buildBsoResultPackage(bsoResult,sha)).includes('NEVER_EXPORT'));
check('BSO blocked result has no body',()=>buildBsoResultPackage(buildQueueResult({error:'SYNTHETIC_NO_PROVIDER'},bsoJob,$execution.id,sha),sha).output==='');

if(tests.some(t=>!t.passed))throw Error('LK_CONTRACT_QA_FAILED '+JSON.stringify(tests));
return [{json:{status:'PASS',contract_version:'lk-execution/1.0',tests_passed:tests.length,external_model_calls:0,synthetic_only:true,tests,synthetic_result:buildQueueResult(result,job,$execution.id,sha)}}];
